# Day of the Tentacle (DOS floppy, Korean patch). One map, two presets; the ini's
# render_target picks one.
#   Default (true colour: render_target=auto): NanumGothic Bold (NGOTB*) and Gowun Batang Bold (GBATB*) faces, 2 bpp, anti-aliased (blend=auto), baked by
#   tools/korean/scumm-fonts/dottu.tsv: a gothic face for the small charsets, Gowun Batang for cs0 and cs7.
#   render_target=clut8 (8-bit palette): Neo Dunggeunmo (NEODG*.SVF), 1 bpp pixel face, drawn hard-edged
#   (tools/korean/scumm-fonts/dottl.tsv).
# Each cell is 2x the patch's korean0N.fnt: cs0 46x54, cs1 16x16, cs2 20x24, cs3/5/8 18x24, cs4 22x22, cs7 36x36.
# The patch has no korean06.fnt; cs6 uses the cs0 face.
# Licences: see NANUMGOT.TXT, GOWUNBAT.TXT and NEODGM.TXT beside this file.
[map]
version=2

[render]
scale=2
blend=auto
[render:clut8]
blend=off

[text]
encoding=cp949

[fonts]
cs0=GBATB47.SVF
cs1=NGOTB15.SVF
cs2=NGOTB19.SVF
cs3=NGOTB17A.SVF
cs4=NGOTB21.SVF
cs7=GBATB35.SVF
[fonts:clut8]
cs0=NEODG32A.SVF
cs1=NEODG16A.SVF
cs2=NEODG16F.SVF
cs3=NEODG16E.SVF
cs4=NEODG16D.SVF
cs7=NEODG32.SVF
fb=SANGAM16.SVF

[font]
missing=u+25a1
range.basic-latin=same
advance.basic-latin=font
# The baked SVF already sets the baseline the Hangul stands on: drop the game
# glyph's own offsets for Latin and punctuation, or ':' '.' sit low (Indy 4's credits).
origin.basic-latin=face
origin.general-punctuation=face

[font.0]
face=cs0
[font.1]
face=cs1
[font.2]
face=cs2
[font.3]
face=cs3
[font.4]
face=cs4
[font.5]
face=cs3
[font.6]
face=cs0
[font.7]
face=cs7
[font.8]
face=cs3

# fb=SANGAM16.SVF (engine data, SAN10.TXT) ends each chain of a face that lives in the jamo font pack, so a missing
# font pack still shows Korean (16 px; only the 8-bit preset has jamo-set faces).
[font.0:clut8]
face=cs0,fb
[font.1:clut8]
face=cs1,fb
[font.2:clut8]
face=cs2,fb
[font.3:clut8]
face=cs3,fb
[font.4:clut8]
face=cs4,fb
[font.5:clut8]
face=cs3,fb
[font.6:clut8]
face=cs0,fb
[font.7:clut8]
face=cs7,fb
[font.8:clut8]
face=cs3,fb

[glyphs]
0x01-0x1f = original
0x5e = original

[glyphs.1]
0x5f = original

[glyphs.4]
0x5f = original
